function proposalDocument(d,code,scale=1){
 const E=esc,M=money,b=d.brand,color=/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#15bfc7';
 const safeImage=u=>/^https:\/\//.test(u||'')?E(u):'';
 const blocks=(value,cls='feature-grid')=>`<div class="${cls}">${proposalM.lines(value).map((line,n)=>{const [head,...rest]=line.split('|');return `<article><span class="index">${String(n+1).padStart(2,'0')}</span><h3>${E(head)}</h3>${rest.length?`<p>${E(rest.join('|'))}</p>`:''}</article>`;}).join('')}</div>`;
 const brand=`${safeImage(b.logo)?`<img class="logo" src="${safeImage(b.logo)}" alt="${E(b.name)}">`:`<div class="wordmark">${E(b.name)}</div>`}`;
 let pages=[];const page=(content,dark=false,extra='')=>pages.push(`<section class="slide ${dark?'dark':''} ${extra}"><header>${brand}<span>${E(code)}</span></header>${content}<footer><span>${E(b.website||b.name)}</span><span>${E(d.client)} · ${String(pages.length+1).padStart(2,'0')}</span></footer></section>`);
 const cover=safeImage(b.cover);page(`${cover?`<img class="cover-photo" src="${cover}" alt="Operação"><div class="cover-shade"></div>`:''}<div class="cover-content"><div class="kicker">${E(d.title)} · ${E(d.client||'Sua empresa')}</div><h1>${E(b.headline)}</h1><p class="lead">${E(b.subtitle)}</p><div class="cover-bottom"><strong>Preparada para ${E(d.contact||d.client||'você')}</strong><span>Emissão ${compactDate(d.issued)} · válida até ${compactDate(d.validUntil)}</span></div></div>`,true,'cover');
 page(`<div class="kicker">01 / CONTEXTO E VALOR</div><h2>Mais clareza para a sua operação.</h2>${d.diagnosis?`<div class="diagnosis"><span class="kicker">O que identificamos juntos</span><p>${E(d.diagnosis).replace(/\n/g,'<br>')}</p></div>`:''}${blocks(b.benefits)}`);
 page(`<div class="kicker">02 / A SOLUÇÃO</div><h2>Recursos que conectam a rotina ao resultado.</h2><p class="lead">O escopo contratado é o descrito em cada condição comercial.</p>${blocks(b.resources)}`,true);
 if(d.options.length>1)page(`<div class="kicker">03 / ESCOLHA SUA CONDIÇÃO</div><h2>Compare o investimento com transparência.</h2><div class="compare-grid">${d.options.map(o=>{const t=proposalM.totals(o);return `<article class="compare-card"><h3>${E(o.name)}</h3><span>Mensalidade inicial</span><strong class="price">${M(t.monthly)}<small>/mês</small></strong><p>Implantação: <b>${M(t.setup)}</b></p><p>Itens pontuais: <b>${M(t.once)}</b></p><p>${o.loyalty?o.loyalty+' meses de fidelidade':'Sem fidelidade'}</p><div class="rule"></div><span>Investimento em 12 meses*</span><strong class="annual">${M(proposalM.periodTotal(o))}</strong></article>`;}).join('')}</div><p class="footnote">*Soma das mensalidades nos preços e períodos desta proposta, implantação e itens pontuais. Não inclui consumo variável ou excedentes. Projeção de 12 meses para comparação; não altera o prazo contratado.</p>`);
 d.options.forEach((o,n)=>{
 const t=proposalM.totals(o),recurring=o.items.some(i=>i.cadence==='monthly'),promos=o.items.filter(i=>i.cadence==='monthly'&&i.promoMonths>0),breaks=[...new Set(promos.map(i=>i.promoMonths+1))].sort((a,b)=>a-b);
 page(`<div class="kicker">CONDIÇÃO ${n+1} / INVESTIMENTO</div><h2>${E(o.name)}</h2><div class="investment-grid"><div><div class="client-label">${E(d.client)}</div><h3>${o.loyalty?'Compromisso de '+o.loyalty+' meses':recurring?'Recorrente sem fidelidade':'Venda pontual'}</h3><p>${E(o.payment)}</p><p>Validade: <strong>${compactDate(d.validUntil)}</strong></p>${o.notes?`<div class="specific-notes">${E(o.notes).replace(/\n/g,'<br>')}</div>`:''}</div><div class="investment-card"><span>${recurring?'Mensalidade inicial · total dos itens recorrentes':'Investimento em itens pontuais'}</span><div class="price">${M(recurring?t.monthly:t.once)}<small>${recurring?'/mês':''}</small></div>${breaks.map(month=>`<p class="price-period">A partir do mês ${month}: <strong>${M(proposalM.totals(o,month).monthly)}/mês</strong></p>`).join('')}<div class="money-row"><span>Implantação total</span><strong>${M(o.setup)}</strong></div><p class="footnote">${o.setup===0?'Implantação sem cobrança nesta condição.':`${o.parts} parcela(s): ${Math.round(o.setup*100)%o.parts?'valores ajustados em centavos para fechar o total':M(o.setup/o.parts)+' por parcela'}.`}</p>${t.once?`<div class="money-row"><span>Itens pontuais</span><strong>${M(t.once)}</strong></div>`:''}<div class="money-row"><span>Projeção de 12 meses*</span><strong>${M(proposalM.periodTotal(o))}</strong></div></div></div><p class="footnote">*Inclui descontos temporários, implantação e itens pontuais. Exclui consumo variável. Datas de cobrança serão alinhadas na contratação.</p>`,true);
 for(let offset=0;offset<o.items.length;offset+=4){const items=o.items.slice(offset,offset+4);page(`<div class="kicker">CONDIÇÃO ${n+1} / ESCOPO ${offset? '· CONTINUAÇÃO':''}</div><h2>O que está incluído em ${E(o.name)}.</h2><div class="scope-grid">${items.map(i=>`<article><span class="kicker">${i.kind==='plan'?'PLANO':'MÓDULO'} · ${i.quantity} unidade(s)</span><h3>${E(i.name)}</h3><p class="item-price">${M(i.price)} por unidade / ${i.cadence==='monthly'?'mês':'venda'}</p>${i.cadence==='monthly'&&i.promoMonths?`<p class="promo">${M(i.promoPrice)} por unidade nos primeiros ${i.promoMonths} meses.</p>`:''}<ul>${proposalM.lines(i.features).map(f=>`<li>${E(f)}</li>`).join('')}</ul>${i.usage?`<p class="usage">${E(i.usage).replace(/\n/g,'<br>')}</p>`:''}</article>`).join('')}</div>`);}
 });
 page(`<div class="kicker">PRÓXIMOS PASSOS</div><h2>Da contratação à operação.</h2>${blocks(b.implementation,'steps')}<div class="terms"><h3>Condições e limites</h3><ul>${proposalM.lines(b.terms).map(t=>`<li>${E(t)}</li>`).join('')}</ul></div><div class="closing"><h3>Vamos começar?</h3><p>${E(b.closing)}</p><strong>${E(d.seller)}</strong><p>${E(d.sellerEmail||b.email)} ${b.phone?' · '+E(b.phone):''}</p></div>`);
 return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${E(code)} · ${E(d.client)}</title><style>
 :root{--accent:${color};--ink:#101a2e;--soft:#eff3f6;--muted:#596879}*{box-sizing:border-box}body{margin:0;background:#dfe5eb;color:var(--ink);font:14px Arial,sans-serif;line-height:1.5}h1,h2,h3,p{margin:0}p{white-space:normal;overflow-wrap:anywhere}h1{font-size:43px;line-height:1.12;letter-spacing:-1.2px;max-width:750px}h2{font-size:31px;line-height:1.2;letter-spacing:-.7px;margin:10px 0 28px}h3{font-size:18px;line-height:1.3;margin:8px 0 10px}strong{font-weight:700}.slide{position:relative;background:white;width:1047px;min-height:718px;margin:22px auto;padding:40px 50px 65px;overflow-wrap:anywhere;break-after:page}.slide:last-child{break-after:auto}.dark{background:#101a2e;color:white}.slide>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:38px;position:relative;z-index:2}.slide>header>span{font-size:10px;letter-spacing:1.5px;color:#8493a6}.wordmark{font-size:21px;font-weight:800;letter-spacing:-.6px}.wordmark:before{content:'';display:inline-block;width:7px;height:19px;background:var(--accent);margin-right:9px;vertical-align:middle}.logo{max-width:180px;max-height:48px;object-fit:contain}footer{position:absolute;left:50px;right:50px;bottom:25px;display:flex;justify-content:space-between;font-size:10px;color:#8493a6}.kicker{color:var(--accent);font-size:11px;font-weight:700;letter-spacing:1.5px}.lead{font-size:18px;color:#617185;max-width:760px;margin:14px 0 28px}.dark .lead,.dark p{color:#c4cfdb}.cover-photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.cover-shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,20,33,.94),rgba(8,20,33,.7) 53%,rgba(8,20,33,.14))}.cover-content{position:relative;z-index:1;padding-top:35px}.cover .kicker{margin-bottom:25px}.cover .lead{max-width:620px;color:#e0e6ee}.cover-bottom{margin-top:60px;border-left:4px solid var(--accent);padding:10px 20px;display:flex;flex-direction:column;gap:6px;font-size:14px}.feature-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:35px}.feature-grid article{padding:20px 0;border-top:2px solid var(--accent)}.feature-grid p{color:var(--muted)}.dark .feature-grid p{color:#c4cfdb}.index{color:var(--accent);font-size:13px;font-weight:bold}.diagnosis{background:var(--soft);padding:20px 24px;border-radius:8px}.diagnosis p{margin-top:8px}.compare-grid{display:grid;grid-template-columns:repeat(${Math.max(1,d.options.length)},1fr);gap:22px}.compare-card{border:1px solid #d8e1e9;border-radius:10px;padding:24px}.compare-card:first-child{border:2px solid var(--accent)}.compare-card>span{font-size:12px;color:var(--muted)}.price{display:block;font-size:35px;font-weight:800;letter-spacing:-1px;line-height:1.25;margin:15px 0 20px}.price small{font-size:13px;letter-spacing:0;font-weight:400;margin-left:7px}.compare-card p{margin-top:8px}.rule{height:1px;background:#d8e1e9;margin:20px 0}.annual{display:block;font-size:23px;margin-top:8px}.footnote{font-size:11px;margin-top:23px;color:#6e7d90}.investment-grid{display:grid;grid-template-columns:1fr 1.2fr;gap:50px}.investment-card{border:1px solid #526073;border-radius:10px;padding:27px}.investment-card>span{font-size:13px;color:#c4cfdb}.client-label{font-size:23px;font-weight:700;margin-bottom:22px}.investment-grid p{margin-bottom:10px}.money-row{border-top:1px solid #526073;display:flex;justify-content:space-between;gap:12px;padding-top:16px;margin-top:18px}.specific-notes{border-left:3px solid var(--accent);padding-left:14px;margin-top:24px;font-size:13px;color:#c4cfdb}.scope-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.scope-grid article{border:1px solid #d8e1e9;border-radius:10px;padding:20px}.scope-grid ul,.terms ul{padding-left:18px;font-size:13px}.scope-grid li,.terms li{margin:5px 0}.item-price{font-size:13px;color:var(--muted)}.promo{font-size:12px;color:#087e83;margin-top:6px}.usage{font-size:11px;color:var(--muted);border-top:1px solid #d8e1e9;padding-top:10px;margin-top:10px}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.steps article{border-top:2px solid var(--accent);padding-top:12px}.steps p{font-size:13px;color:var(--muted)}.terms{margin-top:25px;border-top:1px solid #d8e1e9;padding-top:10px}.terms h3{font-size:15px}.terms ul{font-size:11px}.closing{margin-top:22px;padding:18px 22px;background:var(--soft);border-left:4px solid var(--accent)}.closing h3{margin-top:0}.closing p{font-size:12px;margin-bottom:7px}.closing strong{font-size:13px}
 @media screen{.slide{zoom:${Math.max(.2,Math.min(1,scale))}}} @page{size:A4 landscape;margin:10mm} @media print{body{background:white}.slide{width:277mm;min-height:190mm;margin:0;padding:10mm 13mm 18mm;print-color-adjust:exact;-webkit-print-color-adjust:exact}.slide>header{margin-bottom:9mm}.slide footer{left:13mm;right:13mm;bottom:5mm}.cover-photo,.cover-shade{height:100%;min-height:190mm}.feature-grid article,.scope-grid article,.investment-card,.compare-card,.closing{break-inside:avoid}h2,h3{break-after:avoid}}
 </style></head><body>${pages.join('')}</body></html>`;
}
